(6069024, 892353, 62272, '<td valign="top">I bet this guy never had such a nice portrait taken of him before. Love the way your lighting brings out all his rich textures. I also appreciate the choice of background and vignette in this type of shot.</td>', 'I bet this guy never had such a nice portrait taken of him before. Love the way your lighting brings out all his rich textures. I also appreciate the choice of background and vignette in this type of shot.', '2010-06-24 18:28:01.000000', NULL, 1),
(6069026, 891988, 62272, '<td valign="top">Nice shot. I like the pop of color in the umbrella and the way the perspective of the dock leads the viewers eye to the main subject.</td>', 'Nice shot. I like the pop of color in the umbrella and the way the perspective of the dock leads the viewers eye to the main subject.', '2010-06-24 18:28:57.000000', NULL, 1),
(6069028, 892363, 62272, '<td valign="top">Is this Morro Bay in California? I like your isolation of lighting on the boats. It was a dreamy quality about it.</td>', 'Is this Morro Bay in California? I like your isolation of lighting on the boats. It was a dreamy quality about it.', '2010-06-24 18:29:57.000000', NULL, 1),
(6069030, 892246, 62272, '<td valign="top">lovely</td>', 'lovely', '2010-06-24 18:31:01.000000', NULL, 1),
(6069031, 892524, 62272, '<td valign="top">I like the repetitive patterns and the thing that makes this photo interesting to me is your choice to overlap the textures on the right side of the frame. Nice touch. Without that, this shot would not have been nearly as unique or compelling to look at.</td>', 'I like the repetitive patterns and the thing that makes this photo interesting to me is your choice to overlap the textures on the right side of the frame. Nice touch. Without that, this shot would not have been nearly as unique or compelling to look at.', '2010-06-24 18:32:39.000000', NULL, 1),
(6069036, 892452, 62272, '<td valign="top">you really captured this guys ''evil eye''. i like your choice of solid black for the bg, it works perfect with this subject.</td>', 'you really captured this guys ''evil eye''. i like your choice of solid black for the bg, it works perfect with this subject.', '2010-06-24 18:34:16.000000', NULL, 1),
(6069038, 891221, 62272, '<td valign="top">Love your isolation of color and really love the concentration of light. Good choice of blurring the bottle while making the flower sharp. Very compelling image. Nicely done!</td>', 'Love your isolation of color and really love the concentration of light. Good choice of blurring the bottle while making the flower sharp. Very compelling image. Nicely done!', '2010-06-24 18:34:41.000000', NULL, 1),
(6069041, 892416, 62272, '<td valign="top">very very cool shot. i love the way the rope leads the viewers eye right into the seat of the kayak-- makes me way to jump in and start paddling. the colors are very vibrant, yet not overly saturated. well done!</td>', 'very very cool shot. i love the way the rope leads the viewers eye right into the seat of the kayak-- makes me way to jump in and start paddling. the colors are very vibrant, yet not overly saturated. well done!', '2010-06-24 18:36:01.000000', NULL, 1),
